async function loadPrinterSettings(){try{const e=await fetch("/api/settings/printer");if(e.ok){const t=await e.json();document.getElementById("settings-printer-ip").value=t.ip||"",document.getElementById("settings-printer-ac").value=t.ac||"",document.getElementById("settings-printer-sn").value=t.sn||"",document.getElementById("settings-printer-type").value="true"==t.isX1?1:2,document.getElementById("settings-printer-rtid").value=t.rtid?"true":"false",document.getElementById("settings-printer-rtsb").value=t.rtsb||""}else console.error("Failed to load printer settings")}catch(e){console.error("Error fetching printer settings:",e)}}async function savePrinterSettings(){const e=document.getElementById("settings-printer-ip").value,t=document.getElementById("settings-printer-ac").value,n=document.getElementById("settings-printer-sn").value;let s=document.getElementById("settings-printer-type").value;const o=document.getElementById("settings-printer-rtid").value,i=document.getElementById("settings-printer-rtsb").value;s=1==s?"true":"false";const c=new URLSearchParams;c.append("ip",e),c.append("ac",t),c.append("sn",n),c.append("isX1",s),c.append("rtid","true"===o),c.append("rtsb",i);try{if((await fetch("/api/settings/printer",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:c.toString()})).ok){const e=document.getElementById("alert-saved-printer-settings");e.style.display="block",setTimeout((()=>{e.style.display="none"}),3e3)}else console.error("Failed to save printer settings")}catch(e){console.error("Error saving printer settings:",e)}}async function showTestConnectionModal(){document.getElementById("modal-test-connection-testing").style.display="block",document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="none";new bootstrap.Modal(document.getElementById("modal-test-connection")).show();try{const e=await fetch("/api/test/printer");if(e.ok){const t=await e.json();document.getElementById("modal-test-connection-testing").style.display="none","success"===t.status?(document.getElementById("modal-test-connection-success").style.display="block",document.getElementById("modal-test-connection-fail").style.display="none"):(document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="block")}else console.error("Failed to connect to printer")}catch(e){console.error("Error calling API:",e)}}document.getElementById("btn-modal-test-connection-close").addEventListener("click",(function(){bootstrap.Modal.getInstance(document.getElementById("modal-test-connection")).hide()})),document.getElementById("settings-printer-save").addEventListener("click",(function(e){e.preventDefault(),savePrinterSettings()})),document.getElementById("btn-connection-test").addEventListener("click",(function(){showTestConnectionModal()})),window.onload=function(){loadPrinterSettings(),document.getElementById("alert-saved-printer-settings").style.display="none",document.getElementById("modal-test-connection-success").style.display="none",document.getElementById("modal-test-connection-fail").style.display="none"};